CREATE TABLE IF NOT EXISTS np_users (id INTEGER PRIMARY KEY CHECK(id=1),username TEXT NOT NULL,password TEXT NOT NULL,auth_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS np_sessions (hash TEXT PRIMARY KEY,expires INTEGER NOT NULL,auth_version INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS np_content (id INTEGER PRIMARY KEY CHECK(id=1),version INTEGER NOT NULL,revision TEXT NOT NULL);
INSERT OR IGNORE INTO np_content VALUES(1,0,'seed');
CREATE TABLE IF NOT EXISTS np_chunks (revision TEXT NOT NULL,part INTEGER NOT NULL,text TEXT NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(revision,part));
CREATE TABLE IF NOT EXISTS np_conversations (id TEXT PRIMARY KEY,token_hash TEXT UNIQUE NOT NULL,name TEXT NOT NULL,created INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS np_messages (id INTEGER PRIMARY KEY AUTOINCREMENT,conversation TEXT NOT NULL REFERENCES np_conversations(id) ON DELETE CASCADE,role TEXT NOT NULL,text TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS np_message_conversation ON np_messages(conversation,id);
CREATE TABLE IF NOT EXISTS np_limits (key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
